const m = 1000000007;

function power(a, b) {
    let ans = 1;
    if (b === 0) return 1;
    while (b > 0) {
        if (b % 2 !== 0) {
            ans = (ans * a) % m;
        }
        a = (a * a) % m;
        b = Math.floor(b / 2);
    }
    return ans;
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim();
    let n = parseInt(input, 10);
    let i = 0;
    let index = 0;
    while (n > 0) {
        let rem = n % 10;
        if (rem === 4) {
            index = (index + power(2, i)) % m;
        } else {
            index = (index + power(2, i + 1)) % m;
        }
        n = Math.floor(n / 10);
        i++;
    }
    console.log(index);
}

main();
